    's1_body' => 'यी नियम र सर्तहरू ("नियमहरू") ले हाम्रो वेबसाइट, मोबाइल अनुभव र सम्बन्धित सबै खाता, भुक्तानी, कार्ड तथा सहायता सुविधाहरू (सँगै, "सेवा") सहित Ledger मा तपाईंको पहुँच र प्रयोगलाई नियन्त्रण गर्छन्। खाता बनाएर वा सेवा प्रयोग गरेर, तपाईं यी नियमहरू र तिनमा उल्लेख गरिएका नीतिहरूप्रति बाध्य हुन सहमत हुनुहुन्छ। सहमत हुनुहुन्न भने खाता नबनाउनुहोस् र सेवा प्रयोग नगर्नुहोस्।',
    's2_title' => '२. योग्यता।',
    's2_body' => 'Ledger खाता खोल्न र राख्न तपाईं कम्तीमा १८ वर्षको हुनुपर्छ, बाध्यकारी सम्झौता गर्न सक्षम हुनुपर्छ, र माग गर्दा सरकारले जारी गरेको मान्य परिचय कागजात र स्थायी बसोबास ठेगाना दिन सक्नुपर्छ। हामी तपाईंको पहिचान प्रमाणित गर्न नसके, तपाईं सरकारी प्रतिबन्ध वा निगरानी सूचीमा भए, वा खाता खोल्दा वा राख्दा Ledger कानुनी वा नियामक जोखिममा पर्ने भए, हामी खाता खोल्न अस्वीकार गर्न वा भइरहेको खाता बन्द गर्न सक्छौं।',
    's3_title' => '३. तपाईंको खाता।',
    's3_body' => 'Ledger खाताको मौज्दात Ledger ले बैंकको रूपमा प्रत्यक्ष राख्दैन। रकम एक वा बढी FDIC-बीमित साझेदार बैंकहरूमा संयुक्त संरक्षक खाताहरूमा राखिन्छ, र तपाईंको रकम लागू सीमासम्म FDIC को "पास-थ्रु" निक्षेप बीमाका लागि योग्य छ; यो FDIC नियम, उही साझेदार बैंकमा तपाईंको अन्य रकमसँगको संयोजन र साझेदार बैंकको असफलताको अधीनमा छ। Ledger आफैं एक वित्तीय प्रविधि कम्पनी हो, इजाजतप्राप्त बैंक होइन। लिखित रूपमा अन्यथा सहमति नभएसम्म तपाईं एउटा मात्र व्यक्तिगत खाता राख्न सक्नुहुन्छ, र हाम्रो पूर्व लिखित सहमतिबिना कुनै व्यवसाय, ट्रस्ट वा अर्को व्यक्तिको तर्फबाट रकम प्राप्त गर्न खाता प्रयोग गर्न पाइँदैन।',
    's4_title' => '४. पहिचान प्रमाणीकरण र खाता सीमाहरू।',
    's4_body' => 'संघीय कानुनले वित्तीय सेवा प्रदायकहरूलाई खाता खोल्ने हरेक व्यक्तिको पहिचान गर्ने जानकारी लिन, प्रमाणित गर्न र अभिलेख राख्न अनिवार्य गर्छ। हामी तपाईंलाई फोटोसहितको परिचय कागजात, सेल्फी वा ठेगाना प्रमाण कागजात पेश गर्न भन्न सक्छौं, र त्यो जानकारी समीक्षा भई स्वीकृत नभएसम्म स्थानान्तरण रकम, कार्ड जारी वा अन्य सुविधाहरू सीमित गर्न सक्छौं। हामी समय-समयमा तपाईंको जानकारी पुनः प्रमाणित गर्न सक्छौं र अद्यावधिक जानकारीको अनुरोधको जवाफ नआए प्रभावित सुविधाहरू निलम्बन गर्न सक्छौं।',
    's5_title' => '५. स्थानान्तरण र भुक्तानी।',
    's5_body' => 'सेवाले पैसा सार्ने धेरै तरिकाहरू समर्थन गर्छ, प्रत्येक कारोबारको समयमा देखाइएका सीमा, कट-अफ समय र समीक्षाको अधीनमा: (क) Ledger बाट Ledger स्थानान्तरण, Ledger खाताहरूबीच तुरुन्त पठाइन्छ; (ख) बाह्य बैंक स्थानान्तरण, उही देशको जोडिएको वा छानिएको बैंकमा त्यो बैंकको राउटिङ जानकारी प्रयोग गरी पठाइन्छ; (ग) अन्तर्राष्ट्रिय स्थानान्तरण, तपाईंको देशबाहिरको बैंकमा त्यसको SWIFT/BIC कोड र खाता वा IBAN नम्बर प्रयोग गरी पठाइन्छ, जुन पुग्न बढी समय लाग्न सक्छ, हाम्रो नियन्त्रणबाहिरका मध्यस्थ बैंकहरू हुँदै जान सक्छ, र स्थानान्तरण प्रशोधन हुँदा तोकिएको दरमा मुद्रा रूपान्तरणको अधीनमा हुन सक्छ; (घ) बिल भुक्तानी, तपाईंले तोकेको प्रापकलाई पठाइन्छ; र (ङ) पैसा झिक्ने र टप-अप, जसले तपाईंको Ledger मौज्दात र जोडिएको कार्ड वा बाह्य खाताबीच पैसा सार्छ। प्रापक, राउटिङ, SWIFT/BIC र खाता विवरण पूर्ण र सही हाल्नु तपाईंको जिम्मेवारी हो — तपाईंले दिएको विवरणमा सही रूपमा पठाइएको स्थानान्तरण, ती विवरण गलत भए पनि, Ledger ले फिर्ता गर्न सक्दैन। शंकास्पद ठगी, प्रतिबन्ध जाँच वा अपर्याप्त उपलब्ध मौज्दातका कारण चिन्ह लगाइएमा स्थानान्तरण ढिला हुन, समीक्षाका लागि रोकिन वा अस्वीकृत हुन सक्छ।',
    's6_title' => '६. तालिकामा राखिएका स्थानान्तरण।',
    's6_body' => 'भविष्यको मितिका लागि तालिकामा राखिएको स्थानान्तरण छानिएको मितिमा मात्र पेश हुन्छ र वास्तवमा तपाईंको मौज्दातबाट नगएसम्म ग्यारेन्टी हुँदैन। त्यो मितिअघि जुनसुकै बेला खाता इतिहासबाट तपाईं तालिकामा राखिएको स्थानान्तरण रद्द गर्न सक्नुहुन्छ। तालिकाको मितिमा उपलब्ध मौज्दात अपर्याप्त भए, स्थानान्तरण असफल हुनेछ र इतिहासमा सोही अनुसार चिन्ह लगाइनेछ; पर्याप्त रकम उपलब्ध छ भनी सुनिश्चित गर्नु तपाईंको जिम्मेवारी हो।',
    's7_title' => '७. शुल्कहरू।',
    's7_body' => 'सेवामार्फत सुरु गरिएका Ledger बाट Ledger स्थानान्तरण, बाह्य बैंक स्थानान्तरण, अन्तर्राष्ट्रिय स्थानान्तरण, पैसा झिक्ने वा टप-अपका लागि Ledger ले हाल कुनै शुल्क लिँदैन। तपाईंको जोडिएको बैंक, कार्ड जारीकर्ता वा प्राप्त गर्ने अन्तर्राष्ट्रिय बैंकले अझै पनि आफ्नै शुल्क लगाउन सक्छन् — अन्तर्राष्ट्रिय स्थानान्तरणमा मुद्रा रूपान्तरण, वायर वा मध्यस्थ बैंक शुल्कसहित — जुन हाम्रो नियन्त्रणबाहिर छन् र Ledger ले लिँदैन वा राख्दैन। भविष्यमा Ledger ले कुनै सुविधाका लागि शुल्क सुरु गरेमा, कारोबार पुष्टि गर्नुअघि त्यो तपाईंलाई जानकारी दिइनेछ, र यसलाई वर्णन गर्न यी नियमहरू अद्यावधिक गरिनेछन्।',
    's8_title' => '८. कार्डहरू।',
    's8_body' => 'तपाईंले आफ्नो Ledger मौज्दातसँग जोडिएको भर्चुअल वा भौतिक डेबिट कार्ड अनुरोध गर्नुभयो भने, त्यो कार्ड स्वीकृतिको अधीनमा हुन्छ र जारी भएपछि हरेक खरिदको समयमा तपाईंको उपलब्ध मौज्दातबाट सिधै काटिन्छ — यो क्रेडिट लाइन होइन। हराएको, चोरी भएको वा जोखिममा परेको कार्ड रोक्का वा बन्द गर्न कार्डहरू पृष्ठमार्फत तुरुन्त रिपोर्ट गर्नुपर्छ; रिपोर्ट प्राप्त हुनुअघि भएका कारोबारका लागि तपाईं जिम्मेवार रहनुहुन्छ, लागू कानुन र तलको दफा १० ले सीमित गरेको बाहेक।',
    's9_title' => '९. तपाईंका जिम्मेवारीहरू र खाता सुरक्षा।',
    's9_body' => 'आफ्नो पासवर्ड, कारोबार PIN, दुई-चरण प्रमाणीकरण कोड र Ledger प्रयोग गर्ने उपकरण सुरक्षित राख्नु र कसैसँग साझा नगर्नु तपाईंको जिम्मेवारी हो। तपाईंको खाता, पासवर्ड वा कार्ड जोखिममा परेको लागे, वा नचिनेको कारोबार देखे, सहायता पृष्ठमार्फत तुरुन्त हामीलाई जानकारी दिनुपर्छ। तपाईं आफ्नो सम्पर्क जानकारी, हुलाक ठेगाना र अभिलेखमा रहेका परिचय कागजात अद्यावधिक र सही राख्न सहमत हुनुहुन्छ।',
    's10_title' => '१०. त्रुटि र अनधिकृत कारोबार।',
    's10_body' => 'कुनै स्थानान्तरण, कार्ड शुल्क वा अन्य कारोबार तपाईंको अनुमतिबिना भएको, वा तपाईंको खाता विवरणपत्रमा त्रुटि भएको लागे, सकेसम्म छिटो र गतिविधि इतिहासमा पहिलो पटक देखिएको ६० दिनभित्र सहायता टोलीलाई सम्पर्क गर्नुहोस्। हामी इमानदारीपूर्वक छानबिन गर्नेछौं र छानबिन जारी रहँदा अस्थायी रूपमा रकम फिर्ता गर्न सक्छौं। पुष्टि भएको अनधिकृत कारोबारमा तपाईंको दायित्व लागू कानुनले माग गरेको हदसम्म सीमित छ, तर तपाईंले तुरुन्त हामीलाई जानकारी दिनुभएको हुनुपर्छ र लगइन विवरणको सुरक्षामा ठगीपूर्ण वा घोर लापरवाही गर्नुभएको हुनुहुँदैन।',
    's11_title' => '११. निषेधित प्रयोग।',
    's11_body' => 'तपाईं मनी लाउन्ड्रिङ, आतङ्कवादी वित्तपोषण, ठगी वा प्रतिबन्ध छल्ने लगायत कुनै पनि गैरकानुनी उद्देश्यका लागि सेवा प्रयोग नगर्न; कानुनी रूपमा हकदार नभएको रकम नपठाउन वा प्राप्त नगर्न; अर्को प्रयोगकर्ताको खाता वा Ledger का प्रणालीमा अनधिकृत पहुँचको प्रयास नगर्न; र सेवाको सामान्य सञ्चालनमा हस्तक्षेप नगर्न सहमत हुनुहुन्छ। यो दफा उल्लङ्घन गर्छ भनी उचित रूपमा विश्वास गरिएको कुनै पनि कारोबार हामी अस्वीकार, ढिलाइ, सम्भव भए फिर्ता वा रिपोर्ट गर्न सक्छौं, र कानुनले माग गरेअनुसार कानुन कार्यान्वयन वा नियामक निकायसँग जानकारी साझा गर्न सक्छौं।',
    's12_title' => '१२. खाता स्थिति, निलम्बन र बन्द।',
    's12_body' => 'हामी आफ्नो विवेकमा तपाईंको खाता रोक्का, सीमित, निलम्बन वा बन्द गर्न, वा कुनै खास कारोबार अस्वीकार गर्न सक्छौं — कानुन पालना, शंकास्पद ठगी वा दुरुपयोगको छानबिन, कानुनी वा नियामक अनुरोधको जवाफ, वा तपाईं, अर्को प्रयोगकर्ता वा Ledger को सुरक्षाका लागि आवश्यक छ भनी उचित रूपमा विश्वास गरेको अवस्थासमेत। सम्भव भएसम्म, हामी कारण र सहायता पृष्ठमार्फत हामीलाई कसरी सम्पर्क गर्ने भनी बताउनेछौं। तपाईंको मौज्दात शून्य वा झिकिसकिएको र कुनै खुला छानबिन वा बाँकी कारोबार नभएमा, सहायता टोलीलाई सम्पर्क गरेर तपाईं जुनसुकै बेला खाता बन्द गर्न सक्नुहुन्छ।',
    's13_title' => '१३. सेवाको उपलब्धता; अस्वीकरण।',
    's13_body' => 'हामी सेवा उपलब्ध र सही राख्न काम गर्छौं, तर सेवा "जस्तो छ त्यस्तै" प्रदान गरिन्छ र यो सधैं अवरोधरहित, त्रुटिरहित वा उपलब्ध रहनेछ भनी हामी ग्यारेन्टी गर्दैनौं। साझेदार बैंक, कार्ड नेटवर्क वा मध्यस्थ संस्थामा हुने अवरोध, वा दैवी प्रकोप लगायत हाम्रो उचित नियन्त्रणबाहिरका परिस्थितिले हुने ढिलाइ वा असफलताका लागि हामी जिम्मेवार छैनौं। कानुनले अनुमति दिएको पूर्ण हदसम्म, सेवाको प्रयोगबाट उत्पन्न कुनै पनि दाबीका लागि Ledger को कुल दायित्व त्यो दाबीको कारण बनेको कारोबारको रकमसम्म सीमित छ, उपभोक्ताका वित्तीय खाताहरूको संरक्षण गर्ने कानुनले फराकिलो उपचार माग गरेको अवस्थाबाहेक।',
    's14_title' => '१४. विवाद समाधान।',
    's14_body' => 'तपाईं र Ledger बीच असहमति भए, सिधै समाधान गर्ने प्रयासका लागि पहिले सहायता टोलीलाई सम्पर्क गर्न हामी अनुरोध गर्छौं — धेरैजसो समस्या यसरी नै समाधान हुन्छन्। विवाद अनौपचारिक रूपमा समाधान नभए, कुनै पनि पक्षले लागू कानुनअन्तर्गत उपलब्ध कुनै पनि उपचार खोज्न सक्छ। यी नियमहरूमा भएको कुनै पनि कुराले उपभोक्ता संरक्षण कानुनअन्तर्गत आफ्नो राज्य वा संघीय नियामकसमक्ष विवाद उठाउने तपाईंको अधिकारलाई सीमित गर्दैन।',
    's15_title' => '१५. गोपनीयता।',
    's15_body' => 'हामी तपाईंको व्यक्तिगत र वित्तीय जानकारी कसरी व्यवस्थापन गर्छौं — के सङ्कलन गर्छौं, कसरी प्रयोग गर्छौं, कोसँग साझा गर्न सक्छौं (जस्तै साझेदार बैंक, पहिचान प्रमाणीकरण प्रदायक र सेवा सञ्चालनका लागि आवश्यक कार्ड नेटवर्क), र तपाईंसँग कस्ता विकल्प छन् — यो हाम्रो गोपनीयता अभ्यासहरूमा वर्णन गरिएको छ। हामी तपाईंको पहिचान र खाता जानकारी सेवा सञ्चालन, सुरक्षा र यसमा लागू कानुनको पालनाका लागि मात्र प्रयोग गर्छौं, र तपाईंको व्यक्तिगत जानकारी बेच्दैनौं।',
    's16_title' => '१६. यी नियमहरूमा परिवर्तन।',
    's16_body' => 'सेवा, हाम्रा साझेदार बैंक वा लागू कानुनमा भएका परिवर्तनहरू झल्काउन हामी समय-समयमा यी नियमहरू अद्यावधिक गर्न सक्छौं। महत्त्वपूर्ण परिवर्तन गर्दा, हामी माथिको "पछिल्लो अद्यावधिक" मिति अद्यावधिक गर्नेछौं र कानुनले माग गरेमा थप सूचना दिनेछौं। परिवर्तन लागू भएपछि पनि सेवा प्रयोग जारी राख्नुको अर्थ तपाईंले अद्यावधिक नियमहरू स्वीकार गर्नुभयो भन्ने हो; तपाईं परिवर्तनसँग सहमत हुनुहुन्न भने, सेवा प्रयोग बन्द गरी खाता बन्द गर्नुपर्छ।',
    's17_title' => '१७. लागू कानुन।',
    's17_body' => 'कानुनहरूको द्वन्द्वका सिद्धान्तहरूलाई विचार नगरी, यी नियमहरू संयुक्त राज्य अमेरिका र Ledger को सञ्चालनको मुख्यालय रहेको राज्यका कानुनद्वारा नियन्त्रित हुन्छन्, तपाईं बस्ने क्षेत्राधिकारले फरक कानुन लागू गर्नुपर्ने माग गरेको अवस्थाबाहेक।',
    's18_title' => '१८. हामीलाई सम्पर्क गर्नुहोस्।',
    's18_body' => 'यी नियमहरू, तपाईंको खाता वा कुनै खास कारोबारबारे प्रश्नहरू :support_link पृष्ठमार्फत जुनसुकै बेला पठाउन सकिन्छ।',
    'support_link_text' => 'सहायता',
];
